=<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { background: #f4f4f0; font-family: 'Segoe UI', Arial, sans-serif; padding: 40px 16px; }
    .wrapper { max-width: 560px; margin: 0 auto; }
    .card { background: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 2px 12px rgba(0,0,0,0.08); }

    .header { background: #1a1a1e; padding: 36px 32px; text-align: center; }
    .header-badge { display: inline-block; background: rgba(200,169,110,0.15); color: #c8a96e; font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; padding: 6px 16px; border-radius: 100px; border: 1px solid rgba(200,169,110,0.3); margin-bottom: 16px; }
    .header h1 { color: #f0ede8; font-size: 26px; font-weight: 600; margin-bottom: 6px; }
    .header p { color: #7a7872; font-size: 14px; }

    .score-banner { background: #f9f7f2; border-bottom: 1px solid #eeebe4; padding: 28px 32px; text-align: center; }
    .score-number { font-size: 52px; font-weight: 700; color: #1a1a1e; line-height: 1; }
    .score-number span { font-size: 28px; color: #7a7872; font-weight: 400; }
    .score-pct { font-size: 18px; color: #c8a96e; font-weight: 600; margin-top: 8px; }

    .metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0; border-bottom: 1px solid #eeebe4; }
    .metric { padding: 20px 16px; text-align: center; border-right: 1px solid #eeebe4; }
    .metric:last-child { border-right: none; }
    .metric-value { font-size: 24px; font-weight: 700; color: #1a1a1e; }
    .metric-value.green { color: #1d9e75; }
    .metric-value.red { color: #d85a30; }
    .metric-label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9890; margin-top: 4px; }

    .body { padding: 28px 32px; }
    .section-title { font-size: 11px; text-transform: uppercase; letter-spacing: 0.1em; color: #9a9890; margin-bottom: 12px; font-weight: 600; }

    .summary-box { background: #f9f7f2; border-left: 3px solid #c8a96e; border-radius: 0 10px 10px 0; padding: 16px 20px; margin-bottom: 28px; }
    .summary-box p { font-size: 14px; color: #3a3835; line-height: 1.7; }

    .results-table { width: 100%; border-collapse: collapse; font-size: 13px; }
    .results-table thead tr { background: #f4f4f0; }
    .results-table th { padding: 10px 12px; text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9890; font-weight: 600; }
    .results-table td { padding: 11px 12px; border-bottom: 1px solid #f0ede8; color: #3a3835; vertical-align: middle; }
    .results-table tr:last-child td { border-bottom: none; }

    .badge { display: inline-block; padding: 3px 10px; border-radius: 100px; font-size: 11px; font-weight: 600; }
    .badge.correct { background: #eaf3de; color: #3b6d11; }
    .badge.wrong { background: #faece7; color: #993c1d; }

    .footer { background: #f9f7f2; padding: 24px 32px; text-align: center; border-top: 1px solid #eeebe4; }
    .footer p { font-size: 13px; color: #9a9890; line-height: 1.6; }
    .footer strong { color: #5a5855; }
  </style>
</head>
<body>
  <div class="wrapper">
    <div class="card">

      <!-- Header -->
      <div class="header">
        <div class="header-badge">Exam Results</div>
        <h1>Your Results Are Ready</h1>
        <p>Here's a detailed breakdown of your performance</p>
      </div>

      <!-- Score Banner -->
      <div class="score-banner">
        <div class="score-number">
          {{ $json.marks_scored }}<span>/{{ $json.total_marks }}</span>
        </div>
        <div class="score-pct">{{ $json.score_percentage }}%</div>
      </div>

      <!-- Metrics Row -->
      <div class="metrics">
        <div class="metric">
          <div class="metric-value">{{ $json.total_questions_attempted }}</div>
          <div class="metric-label">Attempted</div>
        </div>
        <div class="metric">
          <div class="metric-value green">{{ $json.correct }}</div>
          <div class="metric-label">Correct</div>
        </div>
        <div class="metric">
          <div class="metric-value red">{{ $json.wrong }}</div>
          <div class="metric-label">Wrong</div>
        </div>
      </div>

      <!-- Body -->
      <div class="body">

        <!-- Performance Summary -->
        <div class="section-title">Performance Summary</div>
        <div class="summary-box">
          <p>{{ $json.performance_summary }}</p>
        </div>

        <!-- Question Breakdown -->
        <div class="section-title">Question Breakdown</div>
        <table class="results-table">
          <thead>
            <tr>
              <th>Q No.</th>
              <th>Your Answer</th>
              <th>Correct Answer</th>
              <th>Marks</th>
              <th>Result</th>
            </tr>
          </thead>
          <tbody>
            {{ $json.results.map(q => `
              <tr>
                <td><strong>Q${q.question_number}</strong></td>
                <td>${q.student_answer}</td>
                <td>${q.correct_answer}</td>
                <td>${q.marks_awarded}</td>
                <td><span class="badge ${q.is_correct ? 'correct' : 'wrong'}">${q.is_correct ? 'Correct' : 'Wrong'}</span></td>
              </tr>
            `).join('') }}
          </tbody>
        </table>

      </div>

      <!-- Footer -->
      <div class="footer">
        <p>This result was automatically generated by the <strong>AI Exam Grader</strong>.<br>
        Keep practicing and you'll keep improving. Good luck!</p>
      </div>

    </div>
  </div>
</body>
</html>
